export function debounce(fn, delay = 200, { now = Date.now } = {}) {
  let pendingArgs = null;
  let scheduledTime = null;
  let timeoutId = null;

  const debounced = (...args) => {
    // Store current args
    pendingArgs = args;
    const callTime = now();
    scheduledTime = callTime + delay;

    const checkAndFlush = () => {
      if (pendingArgs !== null && now() >= scheduledTime) {
        fn(...pendingArgs);
        pendingArgs = null;
        scheduledTime = null;
      }
    };

    // Check if we need to flush immediately
    checkAndFlush();

    // If there was a previous timeout, clear it
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // Set new timeout for lazy boundary flushing
    timeoutId = setTimeout(checkAndFlush, delay);
  };

  debounced.cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    pendingArgs = null;
    scheduledTime = null;
  };

  return debounced;
}

